"""Routes for Health, generated by Dryv; the engine implements SystemHealthService."""

from __future__ import annotations

from abc import ABC, abstractmethod
from collections.abc import Awaitable, Callable

from fastapi import APIRouter, Depends, Request

from mzizi_engine.api.schemas.api.system.models.health import Health
from mzizi_engine.api.schemas.api.system.models.readiness import Readiness

__all__ = ["SystemHealthService", "build_system_health_router"]

type Guard = Callable[[Request], Awaitable[None]]
"""An async FastAPI dependency that raises 401 or 403 before the route runs."""


class SystemHealthService(ABC):
    """What Health needs from handwritten code. Raise ``fastapi.HTTPException`` for failures."""

    @abstractmethod
    async def get_health(self) -> Health:
        """Liveness: the process is up."""

    @abstractmethod
    async def get_readiness(self) -> Readiness:
        """Readiness: each dependency and whether it answers."""


def build_system_health_router(service: SystemHealthService, guard: Guard | None = None) -> APIRouter:
    """Routes for Health, delegating to ``service``; ``guard`` protects every route."""

    router = APIRouter(tags=["Health"], dependencies=[Depends(guard)] if guard else [])

    @router.get(
        "/health",
        response_model=Health,
        status_code=200,
        summary="Liveness: the process is up.",
    )
    async def get_health() -> Health:
        return await service.get_health()

    @router.get(
        "/ready",
        response_model=Readiness,
        status_code=200,
        summary="Readiness: each dependency and whether it answers.",
    )
    async def get_readiness() -> Readiness:
        return await service.get_readiness()

    return router
